import tree_sitter_javascript as tsjavascript
from .ir import FunctionNode, LoopNode, BuiltinCallNode, DataStructureOpNode, IRNode, RecursiveCallNode

JS_LANGUAGE = Language(tsjavascript.language())
parser = Parser(JS_LANGUAGE)

HOFS = {'map', 'filter', 'forEach', 'reduce', 'some', 'every', 'find'}

def get_recursive_calls_js(node, func_name: str) -> tuple[int, str]:
    if node is None: return 0, 'additive'

    total_branch = 0
    overall_shrink = 'additive'

    if node.type == 'call_expression':
        func = node.children[0]
        if func.type == 'identifier' and func.text.decode('utf8') == func_name:
            total_branch += 1
            args_node = _get_child_by_type(node, 'arguments')
            if args_node:
                for arg in args_node.children:
                    arg_text = arg.text.decode('utf8')
                    if any(token in arg_text for token in ('/', '>>', 'mid', 'half', 'slice')):
                        overall_shrink = 'multiplicative'

    if node.type in ('for_statement', 'while_statement', 'for_in_statement', 'for_of_statement'):
        for c in node.children:
            b, s = get_recursive_calls_js(c, func_name)
            total_branch += b * 2
            if s == 'multiplicative': overall_shrink = 'multiplicative'
        return total_branch, overall_shrink

    if node.type == 'if_statement':
        cons = _get_child_by_type(node, 'statement_block')

        alt_branch = 0
        alt_shrink = 'additive'
        for c in node.children:
             if c.type == 'else_clause':
                  b = _get_child_by_type(c, 'statement_block')
                  if not b: b = c # might be a single statement like `else if`
                  b_val, s_val = get_recursive_calls_js(b, func_name)
                  if b_val > alt_branch:
                      alt_branch = b_val
                  if s_val == 'multiplicative': alt_shrink = 'multiplicative'

        c_branch, c_shrink = get_recursive_calls_js(cons, func_name) if cons else (0, 'additive')

        cond_branch = 0
        cond_shrink = 'additive'
        for c in node.children:
            if c.type not in ('statement_block', 'else_clause'):
                b, s = get_recursive_calls_js(c, func_name)
                cond_branch += b
                if s == 'multiplicative': cond_shrink = 'multiplicative'

        final_branch = total_branch + cond_branch + max(c_branch, alt_branch)
        if 'multiplicative' in (overall_shrink, c_shrink, alt_shrink, cond_shrink):
            overall_shrink = 'multiplicative'

        return final_branch, overall_shrink

    for c in node.children:
        b, s = get_recursive_calls_js(c, func_name)
        total_branch += b
        if s == 'multiplicative': overall_shrink = 'multiplicative'

    return total_branch, overall_shrink

def _infer_loop_bound_js(node) -> str:
    if node.type == 'for_statement':
        # look for condition, usually `i < n`
        cond = _get_child_by_type(node, 'binary_expression')
        if cond and len(cond.children) == 3:
            right = cond.children[2]
            if right.type == 'number':
                return 'const'
        return 'linear'

    if node.type == 'while_statement':
        body = _get_child_by_type(node, 'statement_block')
        if body:
            body_text = body.text.decode('utf8')
